export const meta = {
  name: 'clinic-prep-buildable-contract',
  description: 'Research eve.dev/Supabase/Claude, then design a buildable contract, schema, agent, and synthetic primary-care data for a clinic prep assistant',
  phases: [
    { title: 'Research', detail: 'parallel web research on eve.dev, Supabase local, Claude structured outputs, shadcn UI' },
    { title: 'Verify', detail: 'adversarially verify the risky eve.dev claims against real docs' },
    { title: 'Design', detail: 'product contract, Supabase schema, eve agent design, synthetic patient roster' },
    { title: 'Synthetic patients', detail: 'one agent per patient writes a full fictional record + gold briefing' },
    { title: 'Synthesize', detail: 'assemble the final buildable BUILD_PLAN.md' },
  ],
}

const RESEARCH_SCHEMA = {
  type: 'object',
  properties: {
    topic: { type: 'string' },
    summary: { type: 'string' },
    keyFacts: { type: 'array', items: { type: 'string' } },
    commands: { type: 'array', items: { type: 'string' } },
    codeSnippets: { type: 'array', items: { type: 'object', properties: { title: { type: 'string' }, lang: { type: 'string' }, code: { type: 'string' } }, required: ['title', 'code'] } },
    gotchas: { type: 'array', items: { type: 'string' } },
    sources: { type: 'array', items: { type: 'string' } },
    confidence: { type: 'string' },
    unverified: { type: 'array', items: { type: 'string' } },
  },
  required: ['topic', 'summary', 'keyFacts', 'confidence'],
}

const SCHEMA_DESIGN = {
  type: 'object',
  properties: {
    sql: { type: 'string' },
    typesCommand: { type: 'string' },
    seedNotes: { type: 'string' },
    notesMarkdown: { type: 'string' },
  },
  required: ['sql', 'notesMarkdown'],
}

const AGENT_DESIGN = {
  type: 'object',
  properties: {
    agentMarkdown: { type: 'string' },
    skillMarkdown: { type: 'string' },
    toolSignatures: { type: 'string' },
    outputSchemaJson: { type: 'string' },
    systemPrompt: { type: 'string' },
    recommendedModel: { type: 'string' },
  },
  required: ['agentMarkdown', 'outputSchemaJson', 'systemPrompt'],
}

const ROSTER_SCHEMA = {
  type: 'object',
  properties: {
    patients: {
      type: 'array',
      items: {
        type: 'object',
        properties: { id: { type: 'string' }, name: { type: 'string' }, oneLine: { type: 'string' }, challenge: { type: 'string' } },
        required: ['id', 'name', 'oneLine', 'challenge'],
      },
    },
  },
  required: ['patients'],
}

const PATIENT_SCHEMA = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    name: { type: 'string' },
    age: { type: 'integer' },
    sex: { type: 'string' },
    clinicalTheme: { type: 'string' },
    demonstrates: { type: 'string' },
    problemList: { type: 'array', items: { type: 'string' } },
    medications: { type: 'array', items: { type: 'string' } },
    allergies: { type: 'array', items: { type: 'string' } },
    upcomingVisitReason: { type: 'string' },
    priorNotes: {
      type: 'array',
      items: { type: 'object', properties: { date: { type: 'string' }, author: { type: 'string' }, type: { type: 'string' }, text: { type: 'string' } }, required: ['date', 'text'] },
    },
    labs: {
      type: 'array',
      items: { type: 'object', properties: { date: { type: 'string' }, name: { type: 'string' }, value: { type: 'string' }, flag: { type: 'string' } }, required: ['name', 'value'] },
    },
    goldBriefing: {
      type: 'object',
      properties: {
        oneLiner: { type: 'string' },
        keyHistory: { type: 'array', items: { type: 'string' } },
        followUpQuestions: { type: 'array', items: { type: 'object', properties: { question: { type: 'string' }, why: { type: 'string' }, priority: { type: 'string' } }, required: ['question', 'why'] } },
        flags: { type: 'array', items: { type: 'string' } },
        briefingMarkdown: { type: 'string' },
      },
      required: ['oneLiner', 'keyHistory', 'followUpQuestions', 'flags', 'briefingMarkdown'],
    },
  },
  required: ['id', 'name', 'age', 'sex', 'clinicalTheme', 'priorNotes', 'upcomingVisitReason', 'goldBriefing'],
}

const webNote = 'Use your web search tools to find CURRENT real documentation (load WebSearch/WebFetch or the exa/tavily/parallel search tools via ToolSearch if not already available). Do NOT invent or assume APIs — report what the docs ACTUALLY say, with source URLs. If you cannot verify something, put it in the unverified list rather than stating it as fact.'

phase('Research')
const research = await parallel([
  () => agent(
    'Research Vercel\'s eve.dev agent framework (the new "framework for building agents", installed via "npx skills add vercel/eve"). ' + webNote + ' ' +
    'I am building a "clinic prep assistant" agent with it. Determine concretely: (1) how you scaffold/initialize an eve project and the resulting directory structure; (2) how "skills" (markdown instruction files) are authored and discovered; (3) how "tools" (TypeScript functions) are defined, typed, and registered to the agent; (4) how the agent invokes an LLM — does it call Anthropic directly with ANTHROPIC_API_KEY, or via Vercel AI Gateway? what env vars and config select the model (e.g. claude-opus / claude-sonnet)? (5) how durability/workflows work (pause/resume/retry); (6) how you run it locally and deploy to Vercel; (7) whether eve serves an HTTP endpoint the frontend calls, and how to put a Next.js + shadcn UI in front of it; (8) how a tool reads/writes Postgres/Supabase. Provide real code snippets for defining a skill and a tool. Be explicit about what is verified vs. assumed.',
    { label: 'research:eve.dev', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    'Research the CURRENT Supabase LOCAL development workflow on macOS (the user already has the Supabase CLI installed). ' + webNote + ' ' +
    'Cover: initializing a project (supabase init), starting/stopping the local stack (supabase start/stop) and what it spins up (Postgres, Studio, ports), the migrations directory and how to create + apply a migration locally (supabase migration new, supabase db reset / supabase migration up), the seed file (supabase/seed.sql), generating TypeScript types from the local DB (supabase gen types typescript --local), the local connection string + the env vars a TypeScript app needs (SUPABASE_URL, anon/service keys, or direct Postgres URL), how to connect with @supabase/supabase-js vs. a direct Postgres client, and basic RLS (and how to keep it permissive/disabled for a no-auth demo while noting the production lock-down). Give exact commands.',
    { label: 'research:supabase-local', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    'Research how to get RELIABLE structured JSON output from Claude in a TypeScript/Node app, for summarizing clinical notes into a fixed schema (summary, follow-up questions, flags, briefing). ' + webNote + ' ' +
    'Cover BOTH paths: (a) the Anthropic TypeScript SDK using tool-use / tool_choice to force a JSON shape; (b) the Vercel AI SDK generateObject/streamObject with a Zod schema and the Anthropic provider (@ai-sdk/anthropic). Give current, correct model IDs (Opus 4.x, Sonnet 4.x, Haiku) and a clear recommendation for fast, high-quality clinical-note summarization weighing quality vs latency vs cost for a live demo. Note context/token considerations when concatenating multiple prior notes, and how to stream partial structured output to a UI. Provide real, current code snippets.',
    { label: 'research:claude-structured', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    'Research a clean, hackathon-buildable shadcn/ui pattern for a clinical "prep assistant" web UI (the user already has shadcn installed via npx). ' + webNote + ' ' +
    'Design a 3-state single-screen flow: (1) pick or create a patient and paste/upload prior notes (textarea + simple file upload of .txt/.pdf-to-text); (2) a processing/streaming state; (3) the briefing view showing a key-history summary, a list of flagged follow-up questions (with priority), warning flags, and copy/print actions. List the specific shadcn components to use (card, button, textarea, badge, skeleton, scroll-area, separator, tabs, sonner, etc.), a sensible layout, and how this Next.js page calls the eve.dev agent endpoint and renders streamed results. Keep it minimal and implementable in a few hours. Provide a concise component/layout sketch.',
    { label: 'research:shadcn-ui', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
])

const researchOk = research.filter(Boolean)
log('Research complete: ' + researchOk.length + '/4 topics gathered')

phase('Verify')
const eveResearch = researchOk.find(r => r && r.topic && /eve/i.test(r.topic)) || researchOk[0]
const verify = await agent(
  'Adversarially verify these claimed facts about Vercel\'s eve.dev agent framework. ' + webNote + ' ' +
  'For each risky claim — the scaffold/init command, how skills and tools are defined, how the LLM/model is invoked and configured, and how to deploy to Vercel — independently check it against the real current docs/repo. Default to skepticism: if a claim cannot be confirmed from a real source, mark it as UNCONFIRMED and state what the docs actually say instead. Return a corrected, source-cited fact set.\n\nCLAIMS TO CHECK:\n' + JSON.stringify(eveResearch, null, 2),
  { label: 'verify:eve.dev', phase: 'Verify', schema: RESEARCH_SCHEMA }
)

const researchBundle = { topics: researchOk, eveVerification: verify }
const researchText = JSON.stringify(researchBundle, null, 2)

phase('Design')
const [contractMd, schemaDesign, agentDesign, roster] = await parallel([
  () => agent(
    'You are designing the "buildable, shareable contract" for a hackathon project: a CLINIC PREP ASSISTANT for PRIMARY CARE / GP follow-up visits. A doctor uploads/pastes a patient\'s prior notes before an appointment; Claude summarizes key history, flags follow-up questions, and generates a short doctor briefing. ' +
    'Constraints/stack (already decided): eve.dev agent framework; Supabase local; shadcn UI; Claude via the user\'s own Anthropic API key (no AI Gateway); deploy on Vercel; NO Auth0/Resend/Sentry; single demo clinician (no auth). ' +
    'Write a tight, actionable markdown document with these sections: (1) TL;DR (2-3 sentences). (2) The specific person & problem — invent a concrete named PCP persona at a busy community clinic and the exact pain (walking into follow-ups cold / digging through scattered notes between patients). (3) THE CONTRACT — the explicit input -> output guarantee (what goes in, exactly what the app promises to output, what it explicitly does NOT do — it is a prep aid, not diagnosis or treatment advice). (4) In-scope vs out-of-scope for a ~1-day hackathon (ruthless cut-lines). (5) Success criteria. (6) The 90-second demo script, beat by beat, noting what is on screen each beat and which synthetic patient is used. (7) Risks & mitigations. (8) Submission-requirement mapping (GitHub repo, 1:30 video, deploy link, tech list = eve.dev/Vercel/Claude(Anthropic)/Supabase/shadcn, password shipnyc). Be concrete and demo-driven. Markdown only.\n\nRELEVANT RESEARCH:\n' + researchText,
    { label: 'design:contract', phase: 'Design' }
  ),
  () => agent(
    'Design the Supabase (Postgres) data model for the clinic prep assistant (primary-care follow-up; single demo clinician; NO auth). ' +
    'Tables to cover: a single demo clinician; patients (demographics, problem list, meds, allergies); source_notes (raw prior-visit notes with date, author, note type, free text); appointments (the upcoming visit with its reason/context); briefings (the generated output: summary jsonb, follow_ups jsonb, flags jsonb, briefing_md text, model text, status text, token/usage optional, created_at/updated_at). ' +
    'Produce: (a) sql = ONE idempotent migration file (CREATE EXTENSION IF NOT EXISTS pgcrypto for uuid; CREATE TABLE IF NOT EXISTS ...; foreign keys; helpful indexes; an updated_at trigger; RLS left disabled/permissive for the no-auth demo WITH a clearly commented note on how to lock it down for production). Use uuid primary keys with gen_random_uuid(). (b) typesCommand = the exact command to generate TypeScript types from the local DB. (c) seedNotes = how to seed the synthetic patients/notes from a patients.json file (e.g., a seed.sql approach or a small TS seed script reading the JSON). (d) notesMarkdown = a concise explanation of the model, the relationships, and the lifecycle (note -> briefing). Make the SQL directly runnable against a fresh local Supabase Postgres.\n\nRELEVANT RESEARCH:\n' + researchText,
    { label: 'design:schema', phase: 'Design', schema: SCHEMA_DESIGN }
  ),
  () => agent(
    'Design the eve.dev AGENT for the clinic prep assistant, faithful to how eve.dev actually works per the research (skills = markdown instructions, tools = TypeScript). If eve\'s exact model-invocation API is unconfirmed, ALSO give a Vercel AI SDK generateObject fallback so the team is never blocked. Produce: ' +
    '(a) skillMarkdown = the markdown skill/instructions file content: role = clinical PREP assistant for a PCP; strictly grounded in the provided notes; NEVER diagnoses, prescribes, or invents facts; explicitly flags missing, stale, or contradictory information; concise and scannable; output must fit one screen. ' +
    '(b) toolSignatures = TypeScript signatures + brief bodies for the tools: getPatientBundle(patientId) returning notes+meds+labs+allergies+upcoming-visit from Supabase, and saveBriefing(patientId, briefing) persisting the structured result. ' +
    '(c) outputSchemaJson = the JSON Schema (and mention the equivalent Zod) for Claude\'s structured output: summary { oneLiner, activeProblems[], medications[], allergies[], recentChanges[] }, followUpQuestions [{ question, why, priority(high|med|low) }], flags[] (safety/missing-info/contradiction flags), briefingMarkdown (a one-screen briefing). ' +
    '(d) systemPrompt = the exact system prompt for the Claude call. (e) recommendedModel = which Claude model to use for the live demo and why. (f) agentMarkdown = a concise explanation of the end-to-end pipeline (paste/upload -> store note -> agent run -> structured output -> store briefing -> stream to shadcn UI) and how eve\'s durability helps if a model call fails mid-run. Be implementation-ready.\n\nRELEVANT RESEARCH:\n' + researchText,
    { label: 'design:agent', phase: 'Design', schema: AGENT_DESIGN }
  ),
  () => agent(
    'Design a roster of exactly 6 SYNTHETIC, FICTIONAL primary-care follow-up patients for demoing a clinic prep assistant. Each must showcase a DIFFERENT capability of the assistant so the demo feels impressive and varied. Aim to cover: (1) chronic disease management with a medication titration decision (e.g., T2 diabetes + hypertension, trending labs); (2) polypharmacy in an older adult with a subtle but real drug-drug interaction the assistant should flag; (3) notes that CONTRADICT each other (e.g., allergy listed one visit, drug given the next) so the assistant flags the contradiction; (4) a case with MISSING/stale data the assistant should flag as needing follow-up (e.g., overdue labs, no recent BP); (5) a red-flag symptom buried in narrative notes that warrants a specific follow-up question (e.g., unintentional weight loss, new chest pain); (6) a behavioral/lifestyle + mental-health overlap (e.g., anxiety + thyroid, or depression screening due). For each: id (kebab-case), name (clearly fictional), oneLine, and the specific challenge it demonstrates. Return all 6.',
    { label: 'design:roster', phase: 'Design', schema: ROSTER_SCHEMA }
  ),
])

phase('Synthetic patients')
const rosterList = (roster && roster.patients) ? roster.patients : []
const patients = await parallel(rosterList.map((p, i) => () => agent(
  'Write ONE complete, realistic but unmistakably FICTIONAL synthetic primary-care patient record for a clinic prep assistant demo. This is SYNTHETIC data — no real person, no real PII. ' +
  'Patient brief: ' + JSON.stringify(p) + '. ' +
  'Produce a full record: demographics (age, sex), problem list, current medications (with doses), allergies, the upcoming visit reason, 2 to 4 prior visit notes written in AUTHENTIC messy clinician free-text (abbreviations like BP, A1c, c/o, hx, pt, f/u, sob, n/v; vitals; partial sentences; SOAP-ish fragments; realistic dates within the last ~18 months relative to a June 2026 "now"), and a small set of relevant labs with flags. ' +
  'CRITICALLY: bake the specific challenge "' + (p.challenge || '') + '" into the notes so a good assistant produces an impressive, non-obvious flag or follow-up question. ' +
  'Then write the GOLD briefing the assistant SHOULD produce: oneLiner, keyHistory[], followUpQuestions[{question, why, priority}], flags[], and a one-screen briefingMarkdown. The gold briefing is the deterministic demo target and a tiny eval reference. Keep it clinically plausible but clearly fictional (use obviously fake names). Vary tone/handwriting-style across notes (variant index ' + i + ').',
  { label: 'patient:' + (p.id || ('p' + i)), phase: 'Synthetic patients', schema: PATIENT_SCHEMA }
)))

const patientsOk = patients.filter(Boolean)
log('Synthetic patients written: ' + patientsOk.length + '/' + rosterList.length)

phase('Synthesize')
const final = await agent(
  'Assemble the FINAL "buildable, shareable contract" document (BUILD_PLAN.md) for the clinic prep assistant hackathon project. Weave the inputs below into ONE cohesive, tight, skimmable markdown doc. Sections: ' +
  'Title + TL;DR; The person & the problem; THE CONTRACT (input -> output, and what it explicitly does not do); Architecture (a text diagram showing shadcn/Next.js UI -> eve.dev agent (skills+tools) -> Claude (Anthropic key) + Supabase local); Tech stack & why each piece; Data model (summarize, and reference docs/schema.sql); The agent (summarize the skill, tools, structured output schema, recommended Claude model; reference docs/agent-design.md); Synthetic data (summarize the 6-patient roster as a table and reference synthetic-data/patients.json + patients.md, noting each patient demonstrates a distinct capability); The 90-second demo script (beat by beat); Hackathon build plan (a timeboxed, checkbox milestone list from empty repo to deployed); Setup commands (exact, end-to-end: install, supabase init/start/migrate/seed, gen types, run eve agent locally, run the Next.js UI, deploy to Vercel; note the user already has shadcn, an Anthropic API key, and a Vercel key); Submission checklist (GitHub repo, 1:30 video, deploy link, tech list, password shipnyc); Risks & cut-lines. Keep it practical and motivating, no fluff. Markdown only.\n\n' +
  '=== PRODUCT CONTRACT DRAFT ===\n' + (contractMd || '(missing)') + '\n\n' +
  '=== DATA MODEL NOTES ===\n' + ((schemaDesign && schemaDesign.notesMarkdown) || '(missing)') + '\n\n' +
  '=== AGENT DESIGN ===\n' + ((agentDesign && agentDesign.agentMarkdown) || '(missing)') + '\n\n' +
  '=== PATIENT ROSTER ===\n' + JSON.stringify(rosterList) + '\n\n' +
  '=== KEY RESEARCH FACTS ===\n' + researchText.slice(0, 12000),
  { label: 'synthesize:build-plan', phase: 'Synthesize' }
)

return {
  buildPlanMarkdown: final,
  schema: schemaDesign,
  agent: agentDesign,
  roster: rosterList,
  patients: patientsOk,
  research: researchBundle,
}

