// Computer-use test: emulate an iPhone, sign in through the gate, generate a
// briefing, and screenshot it. Usage: node scripts/shot.mjs [url] [out.png] [patient]
import { chromium, devices } from "playwright";

const BASE = process.argv[2] || "https://clinic-prep-assistant.vercel.app";
const OUT = process.argv[3] || "/tmp/briefing_mobile.png";
const PATIENT = process.argv[4] || "Walter Okonkwo";
const EMAIL = process.env.APP_EMAIL || "a.kar.wright@gmail.com";
const PASS = process.env.APP_PASSWORD || "vercelship";

const iPhone = devices["iPhone 14 Pro"] || devices["iPhone 13"];
const browser = await chromium.launch();
const ctx = await browser.newContext({ ...iPhone });
const page = await ctx.newPage();
page.on("response", (r) => {
  if (r.url().includes("/api/prep") || r.url().includes("/api/login")) {
    console.log("  " + r.url().replace(BASE, "") + " ->", r.status());
  }
});

const t0 = Date.now();
await page.goto(BASE, { waitUntil: "domcontentloaded" });

// Gate: if bounced to /login, sign in.
if (page.url().includes("/login")) {
  console.log("gate -> signing in as", EMAIL);
  await page.fill('input[type="email"]', EMAIL);
  await page.fill('input[type="password"]', PASS);
  await page.getByRole("button", { name: /log in/i }).click();
  await page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 25000 }).catch(() => {});
  console.log("after login:", page.url());
}

await page.waitForSelector('input[placeholder*="Search"]', { timeout: 20000 });
await page.fill('input[placeholder*="Search"]', "Walter");
await page.waitForTimeout(600);
await page.getByText(PATIENT, { exact: false }).first().click();
await page.waitForTimeout(300);
await page.getByRole("button", { name: /Generate briefing/i }).first().click();
console.log("clicked Generate");

await page
  .waitForSelector("text=/Follow|Watch|Flags|Trends|Summary|Ask|Snapshot/i", { timeout: 60000 })
  .then(() => console.log("briefing rendered in", ((Date.now() - t0) / 1000).toFixed(1), "s"))
  .catch(() => console.log("WARN: briefing selector not found"));
await page.waitForTimeout(1500);
await page.screenshot({ path: OUT, fullPage: true });
console.log("screenshot saved to", OUT);
await browser.close();
process.exit(0);

