{trends && trends.length > 0 && (
  <>
    <SectionHeading count={trends.length}>Trends</SectionHeading>
    <Card elevated className="mb-5 p-3.5 sm:p-4">
      {/* Fixed-width sparks scroll on tiny screens rather than distort. */}
